//! Binary form: `Vec::<u8>::from(&module)` / `Module::try_from(bytes)`, lossless like the text form, and the way to
//! store / ship bytecode (no text to parse, no mnemonics to look up).
//!
//! ```text
//! magic  "\0j8b"          4 bytes (`Module::MAGIC`; a leading NUL never starts JS or assembly text)
//! schema u64 LE           fingerprint of insn.json: only reads back under the same instruction set
//! module                  `Binary` of `Module`
//! ```
//!
//! `Binary` for the types in insn.json is generated by `enums!`: an enum is a one-byte tag (the variant's position
//! in the JSON) and then its fields, a struct is its fields in order. The field types not in the JSON are here:
//! integers / `f64` fixed-width little-endian, `bool` one byte, `Box<str>` and `Vec<T>` a `u32` length then the
//! contents, `Option<T>` a one-byte tag then the value.
use alloc::boxed::Box;
use alloc::vec::Vec;
use core::fmt;

use crate::Module;
use crate::insn::SCHEMA;

/// A binary decoding error.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum BinError {
    /// Does not start with `Module::MAGIC`: not j8 bytecode
    Magic,
    /// Written under another instruction set (the schema it carries)
    Schema(u64),
    /// Ran out of bytes
    Eof,
    /// Unknown tag for the type (named first)
    Tag(&'static str, u8),
    /// A string that is not UTF-8
    Utf8,
    /// Bytes left over after the module
    Trailing(usize),
}

impl fmt::Display for BinError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BinError::Magic => f.write_str("not j8 bytecode (bad magic)"),
            BinError::Schema(got) => write!(f, "bytecode for another instruction set (schema {got:#018x}, expected {SCHEMA:#018x})"),
            BinError::Eof => f.write_str("unexpected end of bytecode"),
            BinError::Tag(ty, tag) => write!(f, "bad {ty} tag {tag}"),
            BinError::Utf8 => f.write_str("string is not UTF-8"),
            BinError::Trailing(n) => write!(f, "{n} bytes after the module"),
        }
    }
}

impl core::error::Error for BinError {}

/// A cursor over the bytes being decoded.
pub struct Reader<'a>(&'a [u8]);

impl<'a> Reader<'a> {
    fn bytes(&mut self, n: usize) -> Result<&'a [u8], BinError> {
        let (head, rest) = self.0.split_at_checked(n).ok_or(BinError::Eof)?;
        self.0 = rest;
        Ok(head)
    }

    fn array<const N: usize>(&mut self) -> Result<[u8; N], BinError> {
        let (head, rest) = self.0.split_first_chunk().ok_or(BinError::Eof)?;
        self.0 = rest;
        Ok(*head)
    }

    /// One byte (an enum tag)
    pub fn byte(&mut self) -> Result<u8, BinError> {
        self.array::<1>().map(|[b]| b)
    }

    /// A `u32` length (of a string / a `Vec`)
    fn len(&mut self) -> Result<usize, BinError> {
        u32::decode(self).map(|n| usize::try_from(n).unwrap_or(usize::MAX))
    }
}

/// Binary encoding, inverse of decoding.
pub trait Binary: Sized {
    fn encode(&self, out: &mut Vec<u8>);
    fn decode(r: &mut Reader<'_>) -> Result<Self, BinError>;
}

/// Fixed-width little-endian
macro_rules! le {
    ($($ty:ty),*) => {$(
        impl Binary for $ty {
            fn encode(&self, out: &mut Vec<u8>) {
                out.extend_from_slice(&self.to_le_bytes());
            }
            fn decode(r: &mut Reader<'_>) -> Result<Self, BinError> {
                r.array().map(<$ty>::from_le_bytes)
            }
        }
    )*};
}
le!(u16, u32, i32, u64, f64);

impl Binary for bool {
    fn encode(&self, out: &mut Vec<u8>) {
        out.push(u8::from(*self));
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BinError> {
        match r.byte()? {
            0 => Ok(false),
            1 => Ok(true),
            b => Err(BinError::Tag("bool", b)),
        }
    }
}

impl Binary for Box<str> {
    fn encode(&self, out: &mut Vec<u8>) {
        u32::try_from(self.len()).unwrap_or(u32::MAX).encode(out);
        out.extend_from_slice(self.as_bytes());
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BinError> {
        let n = r.len()?;
        let bytes = r.bytes(n)?;
        core::str::from_utf8(bytes).map(Box::from).map_err(|_| BinError::Utf8)
    }
}

impl<T: Binary> Binary for Vec<T> {
    fn encode(&self, out: &mut Vec<u8>) {
        u32::try_from(self.len()).unwrap_or(u32::MAX).encode(out);
        for x in self {
            x.encode(out);
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BinError> {
        let n = r.len()?;
        // Never reserves more than the bytes left could hold (a corrupt length fails at Eof, not in the allocator)
        let mut items = Vec::with_capacity(n.min(r.0.len()));
        for _ in 0..n {
            items.push(T::decode(r)?);
        }
        Ok(items)
    }
}

impl<T: Binary> Binary for Option<T> {
    fn encode(&self, out: &mut Vec<u8>) {
        match self {
            None => out.push(0),
            Some(x) => {
                out.push(1);
                x.encode(out);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BinError> {
        match r.byte()? {
            0 => Ok(None),
            1 => T::decode(r).map(Some),
            b => Err(BinError::Tag("Option", b)),
        }
    }
}

impl Module {
    /// Is this j8 bytecode in binary form (by the magic alone; the schema is checked when decoding)
    pub fn is_binary(bytes: &[u8]) -> bool {
        bytes.starts_with(&Self::MAGIC)
    }
}

impl From<&Module> for Vec<u8> {
    fn from(m: &Module) -> Self {
        let mut out = Vec::from(Module::MAGIC);
        SCHEMA.encode(&mut out);
        m.encode(&mut out);
        out
    }
}

impl TryFrom<&[u8]> for Module {
    type Error = BinError;

    fn try_from(bytes: &[u8]) -> Result<Self, BinError> {
        let mut r = Reader(bytes.strip_prefix(&Self::MAGIC).ok_or(BinError::Magic)?);
        match u64::decode(&mut r)? {
            SCHEMA => {}
            got => return Err(BinError::Schema(got)),
        }
        let module = Self::decode(&mut r)?;
        match r.0.len() {
            0 => Ok(module),
            n => Err(BinError::Trailing(n)),
        }
    }
}
